/* What Gratifi does, step by step. Every flow returns what to say, the steps it took and the blocks to show.
   The AI calls these as tools; buttons call them directly. Money and points only move after the customer confirms in the
   confirm sheet (confirmPay, or an action confirm), and every refund checks the booking hasn't already been refunded. */
import * as St from './store'
import * as Mod from './modules'
import * as Cat from './catalog'
import { fmt } from '../../kit/src/market'

export type PayChoice = { method: 'points' | 'mix' | 'card'; pts: number; card: number }
export type Confirm = { kind: 'pay'; draft: string; choice: PayChoice } | { kind: 'action'; title: string; summary?: string; lines?: [string, string][]; total?: [string, string]; cta?: string; act: { f: string; a?: any } }
export type R = { say?: string; blocks: St.Block[]; steps?: string[]; summary?: any; suggest?: string[]; confirm?: Confirm }
const M = () => fmt(St.get().market)
const mk = () => St.get().market
const base = () => (mk() === 'AR' ? 'AE' : mk())
export const P = (gbp: number) => Cat.px(gbp, mk())
/** Everyday local prices follow the local price level, not just the exchange rate. */
const LEVEL: Record<string, Record<string, number>> = {
  quick: { IN: 0.25, MY: 0.5, SG: 1, AE: 1, EU: 1, UK: 1 }, rides: { IN: 0.3, MY: 0.3, SG: 0.45, AE: 0.35, EU: 1, UK: 1 }, experiences: { IN: 0.45, MY: 0.6, SG: 1, AE: 1, EU: 1, UK: 1 },
  tickets: { IN: 0.4, MY: 0.6, SG: 1, AE: 1, EU: 1, UK: 1 }, subs: { IN: 0.3, MY: 0.5, SG: 0.9, AE: 0.9, EU: 1, UK: 1 }, docs: { IN: 0.5, MY: 0.6, SG: 1, AE: 1, EU: 1, UK: 1 },
}
export const local = (cat: string) => LEVEL[cat]?.[base()] ?? 1
const EXTRAS: Record<string, number> = { IN: 0.25, MY: 0.3, SG: 0.8, AE: 0.8 }
export const legroomFee = () => P(28 * (EXTRAS[base()] ?? 1))
export const bagUnit = () => P(32 * (EXTRAS[base()] ?? 1))
export const stayDefault = () => { const f = iso(nextFriday()); return f < addDays(iso(new Date()), 4) ? addDays(f, 7) : f }
export const groceryFee = () => (base() === 'IN' ? 29 : P(1.99 * local('quick')))
export const IP = (i: { gbp: number; cat: string }) => P(i.gbp * local(i.cat))
export const giftAmounts = () => ({ IN: ['500', '1000', '2000', '5000'], AE: ['50', '100', '250', '500'], AR: ['50', '100', '250', '500'], MY: ['50', '100', '200', '500'] } as any)[mk()] || ['25', '50', '100', '200']
export const ptsOf = (price: number) => Math.max(0, Math.round(price / St.rate()))
const pts = ptsOf
export const loc = (s: string) => s.replace(/£([\d,.]+)(m)?/g, (_, n, u) => { const v = parseFloat(n.replace(/,/g, '')); return M().money(Cat.px(u ? v * 1e6 : v, mk())) })
const dead = (b: St.Booking) => ['cancelled', 'refunded'].includes(b.status)
const paidTxt = (b: { pts: number; card: number }, f = 1) => [b.pts ? M().pts(Math.round(b.pts * f)) : '', b.card ? M().money(b.card * f, 2) : ''].filter(Boolean).join(' + ')

/* ---------- dates, people, places ---------- */
