  const tracker = kind === 'order' && i.cat !== 'giftcards' ? { steps: ['Order placed', 'Packed', 'Out for delivery', 'Delivered'], current: 1, eta: i.cat === 'quick' ? '15 min' : M().date(a.ship || addDays(iso(new Date()), 2)) } : i.cat === 'rides' && /Ride/.test(i.title) ? (a.at ? { steps: ['Booked', 'Driver assigned', 'Arrived', 'Trip done'], current: 0, eta: a.at } : { steps: ['Driver assigned', 'On the way', 'Arrived', 'Trip done'], current: 1, eta: i.sub?.match(/(\d+ min)/)?.[1] || '4 min' }) : undefined
