  const d = St.draft({ cat: i.cat, title: i.cat === 'giftcards' ? `${i.title} gift card` : i.title, sub: /^Ride/.test(i.title) && a.dest ? `To ${a.dest}` : [i.cat === 'tickets' ? i.sub?.split(' · ')[0] : i.sub, !isTime && a.option && !['giftcards', 'rides'].includes(i.cat) ? (i.opts?.label === 'Size' && i.cat === 'shopping' ? 'Size ' : '') + a.option.replace(/ \(\+.*\)/, '') : ''].filter(Boolean).join(' · '), when, qty, unit, total, itemId: i.id, icon: i.icon || (i.cat === 'tickets' ? 'ticket' : undefined), img: i.img, ...timedPolicy(i.policy, !/non-refundable|no refunds|not refundable/i.test(i.policy || ''), startTs(a.date, a.at || (/^\d{1,2}:\d\d/.test(a.option || '') ? a.option!.slice(0, 5) : undefined), i.cat), i.cat), kind, tracker, detail, extra: { at: a.at, option: a.option, to: a.to, email: a.email, dest: a.dest, date: a.date || (i.cat === 'dining' ? iso(new Date()) : undefined), included: freeN > 0 || (unit === 0 && !!i.included), freeN, pair: i.unit === 'for two' || undefined, nights, mult: +(i.earn?.match(/^(\d+)×/)?.[1] || 1) } })
