/* ---------- travel essentials ---------- */
export function docs(a: { topic: string; city?: string }): R {
  const t = a.topic.toLowerCase().replace(/\b(the us|usa|united states|america)\b/, 'new york').replace(/\b(the uk|britain|england)\b/, 'london'), m = mk(), city = a.city ? Cat.findCity(m, a.city) : Cat.findCity(m, t)
  const asked = !city ? (a.topic.match(/\b(?:for|to|in|visit(?:ing)?)\s+([A-Z][a-zA-Z]+(?: [A-Z][a-zA-Z]+)?)/)?.[1] || '') : ''
  if (/visa|entry|passport/.test(t) && asked && !/^(my|the|a|it)$/i.test(asked)) return { say: `I hold entry rules for the places I can book. For ${asked}, check your government's official travel advice before you go.`, blocks: [{ kind: 'places' }] }
  if (/visa|entry|passport/.test(t)) return { say: city ? `For ${city.name}, entry rules depend on your passport. Here's what applies and where to check it.` : 'Where are you going? I\'ll check the entry rules for your passport.', blocks: city ? [{ kind: 'visa', city: city.name }] : [{ kind: 'places', mode: 'visa' }] }
  if (/insur|cover/.test(t) && /ski|snowboard|winter sport/.test(t)) return { say: 'None of these policies cover winter sports. The concierge team can find one that does.', blocks: [{ kind: 'conciergeform', hint: a.topic }] }
  if (/insur|cover/.test(t)) return { say: 'Your card already includes travel insurance when you pay for the trip with it. If you want more, these top up.', blocks: [{ kind: 'insurance' }] }
  if (/esim|data|roaming|sim/.test(t)) return { say: 'Data abroad without roaming charges. It installs in about a minute.', blocks: [{ kind: 'esim' }] }
  if (/forex|currency|cash|money abroad|abroad/.test(t)) return { say: 'Your card has no foreign transaction fee, so paying by card abroad is usually cheapest. Cash machines may charge their own fee.', blocks: [{ kind: 'controls' }] }
  return { say: 'Travel essentials: entry rules, cover and data.', blocks: [{ kind: 'essentials' }] }
}

