export function alertSet(a: { what: string }): R { const w0 = String(a.what || '').trim().replace(/\.$/, '').replace(/\bmy\b/gi, 'your').replace(/\bI am\b|\bI'm\b/g, 'you are').replace(/\bI\b/g, 'you').replace(/^(When|If|As soon as|Before|On) /, (x: string) => x.toLowerCase()); const w = /^(when|if|as soon as|before|on) /.test(w0) ? w0 : `when ${w0}`; St.set(s => ({ seen: { ...s.seen, ['alert:' + w]: true } })); return { say: `Saved: an alert ${w.replace(/\.$/, '')}. It's listed under Alerts on My card, where you can remove it.`, blocks: [{ kind: 'alertcard', k: 'alert:' + w }] } }
